// Edited-XLSX patch tests (F5), anchored to REAL Contract C5 producer workbooks.
//
// The fixtures under `optimize/__fixtures__/c5/` are generated by the actual
// backend exporter (see `generate-c5-goldens.py`), so these tests patch genuine
// C5 OOXML — history columns, frozen panes, the Score/Status boundary, and a
// real Notes sheet with bidirectional hyperlinks — not a synthetic round-trip.
//
// Per the orchestrator's correction: the adversarial multi-notes / multi-cell
// matrix is built by loading the genuine `c5-notes-hyperlinks.xlsx` and ENRICHING
// its existing Notes sheet in-test (extra notes for one edited cell + another
// noted cell + matching hyperlinks), then feeding those bytes to the production
// patcher — real C5 structure, constructed adversarial input.

import { execFileSync, spawnSync } from "node:child_process";
import { readFileSync, rmSync, writeFileSync } from "node:fs";
import { dirname, join } from "node:path";
import { fileURLToPath } from "node:url";

import ExcelJS from "exceljs";
import { describe, expect, it } from "vitest";

import {
  buildEditedCellPatches,
  EditedXlsxError,
  patchFrozenXlsxWithEdits,
  tryPatchFrozenXlsxWithEdits,
} from "./edited-xlsx";
import { fixtureRosterDocument } from "./test-fixtures";
import type { RosterCoordinateMap, RosterEdit } from "./types";

const FIXTURES_DIR = join(
  dirname(fileURLToPath(import.meta.url)),
  "..",
  "optimize",
  "__fixtures__",
  "c5",
);

interface FixtureMeta {
  file: string;
  peopleCount: number;
  columnAIds: string[];
  prettify: boolean;
}

const MANIFEST: Record<string, FixtureMeta> = JSON.parse(
  readFileSync(join(FIXTURES_DIR, "manifest.json"), "utf-8"),
);

function fixtureBytes(file: string): Uint8Array {
  return new Uint8Array(readFileSync(join(FIXTURES_DIR, file)));
}

function fixtureBlob(file: string): Blob {
  return new Blob([fixtureBytes(file) as BlobPart], {
    type: "application/vnd.openxmlformats-officedocument.spreadsheetml.sheet",
  });
}

async function reRead(blob: Blob): Promise<ExcelJS.Workbook> {
  const wb = new ExcelJS.Workbook();
  await wb.xlsx.load((await blob.arrayBuffer()) as unknown as ArrayBuffer);
  return wb;
}

/**
 * The coordinate map the exporter produces for a C5 fixture. `historyCols` is the
 * global max history length when prettify is on (the generator gives P1 a single
 * history entry, so it is 1); the date columns follow the exact exporter formula
 * `leadingCols + historyCols + 1 + dateIdx`.
 */
function fixtureCoordinateMap(meta: FixtureMeta): RosterCoordinateMap {
  const historyCols = meta.prettify ? 1 : 0;
  const peopleRows = Array.from({ length: meta.peopleCount }, (_, i) => 3 + i);
  // The generator scenario always spans 3 dates.
  const dateColumns = Array.from({ length: 3 }, (_, i) => 1 + historyCols + 1 + i);
  return {
    peopleRows,
    dateColumns,
    firstPeopleRow: 3,
    leadingCols: 1,
    historyCols,
    prettify: meta.prettify,
  };
}

/** The provenance a roster document carries; values are not load-bearing here. */
function fixtureProvenance() {
  return {
    solverStatus: "OPTIMAL" as const,
    score: 9,
    solvedBaselineId: "abc123def456",
    appBuild: "0.0.0-test",
  };
}

// --- Optional independent openpyxl semantic diff --------------------------------

const DIFF_PYTHON = detectDiffPython();

function detectDiffPython(): string | null {
  for (const candidate of [process.env.XLSX_DIFF_PYTHON, "python3", "python"]) {
    if (!candidate) continue;
    const probe = spawnSync(candidate, ["-c", "import openpyxl"], { encoding: "utf-8" });
    if (probe.status === 0) return candidate;
  }
  return null;
}

interface SemanticDiffEntry {
  kind: string;
  sheet?: string;
  coord?: string;
}

function semanticDiff(
  originalBytes: Uint8Array,
  patched: Uint8Array,
  label: string,
): SemanticDiffEntry[] {
  const origTmp = join(FIXTURES_DIR, `.orig.${label}.tmp.xlsx`);
  const patchedTmp = join(FIXTURES_DIR, `.patched.${label}.tmp.xlsx`);
  writeFileSync(origTmp, originalBytes);
  writeFileSync(patchedTmp, patched);
  try {
    const out = execFileSync(
      DIFF_PYTHON as string,
      [join(FIXTURES_DIR, "xlsx-semantic-diff.py"), origTmp, patchedTmp],
      { encoding: "utf-8" },
    );
    return (JSON.parse(out).diffs as SemanticDiffEntry[]) ?? [];
  } finally {
    rmSync(origTmp, { force: true });
    rmSync(patchedTmp, { force: true });
  }
}

/**
 * Strip the dedicated provenance sheet from a patched workbook so the openpyxl
 * diff (which short-circuits on a sheetname mismatch) proceeds to cell-level
 * comparison. The provenance sheet's presence is asserted separately; this is
 * only for proving unedited schedule cells are byte-faithful.
 */
async function stripProvenanceSheet(patched: Uint8Array): Promise<Uint8Array> {
  const wb = new ExcelJS.Workbook();
  await wb.xlsx.load(patched as unknown as ArrayBuffer);
  const provenance = wb.worksheets.find((ws) => ws.name === "Roster provenance");
  if (provenance !== undefined) wb.removeWorksheet(provenance.id);
  const buffer = await wb.xlsx.writeBuffer();
  return new Uint8Array(buffer as ArrayBuffer);
}

